/* -----------------------------------------------------------------------
 * test_ui.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: Tony; Brendon (integrator) updated the effect labels (Sep 2026), added test groups N, O and P plus Battery-screen cases (28 Oct 2026), the whole-card file list and Delete row cases and group R (29-30 Oct 2026, with an AI coding assistant).
 * BJT2 Sound Modulating Toy — Complete UI Subsystem Unit Tests
 * Author: Tony (Display/UI subsystem)
 *
 * Covers all six modules using the Unity test framework.
 * No hardware required — runs on any host PC via CMake.
 *
 * Test groups:
 *   Group A — State machine: init and home screen navigation
 *   Group B — State machine: Record screen
 *   Group C — State machine: Play screen (playback + autotune)
 *   Group D — State machine: Volume screen (inc/dec/clamp/mute)
 *   Group E — State machine: File screen (scroll/select)
 *   Group F — State machine: cross-screen isolation
 *   Group G — Touch calibration (Module 2)
 *   Group H — Hit testing (Module 3)
 *   Group I — Touch-to-event mapping (Module 4)
 *   Group J — Display logic and battery conversion (Module 5), incl.
 *             the Battery screen lines and the hh:mm time formatter
 *   Group K — Encoder state machine (Module 6)
 *   Group L — Full pipeline: ADC counts -> event -> state change
 *   Group N — Critical-battery speaker lockout (display lines, stored
 *             volume/mute, nothing in the state machine clears it)
 *   Group O — Fault screen (modal overlay: open, dedupe, replace, any
 *             input dismisses and does nothing else, display lines)
 *   Group P — Hidden debug screen (enter from Home only, encoder cursor,
 *             BACK exits, push / PLAY / REC and touch change nothing,
 *             fault overlay returns to it, BACK-hold pipeline)
 *   Group Q — Effects: a tap picks the tapped row (it becomes the cursor
 *             and toggles; the encoder push carries on from it; the pick
 *             events change nothing on other screens)
 *   Group R — Effect files: "Preparing nn%" and "Effect: None (n/a)" on
 *             the Play screen, following Jack to idle by the command seq,
 *             the REC clock started by Jack's status
 * ----------------------------------------------------------------------- */

#include "unity.h"
