/* Shared instances reused across tests */
static ui_state_t   s;
static encoder_sm_t enc;
static display_info_t disp;

/* Helper — feed a sequence of pin states to the encoder */
static ui_event_t enc_feed(encoder_sm_t *e, bool a, bool b)
{
    encoder_pins_t p = { a, b };
    return encoder_sm_update(e, p);
}

