void test_A15_home_cursor_starts_on_record(void)
{
    ui_init(&s);
    TEST_ASSERT_EQUAL(UI_SCREEN_RECORD, s.home_highlighted);
}

void test_A16_encoder_cw_moves_home_cursor_down(void)
{
    ui_init(&s);
    ui_process_event(&s, EVENT_VOLUME_UP);
    TEST_ASSERT_EQUAL(UI_SCREEN_PLAY, s.home_highlighted);
}

void test_A17_encoder_ccw_wraps_from_record_to_battery(void)
{
    ui_init(&s);
    /* cursor starts on Record — scrolling up wraps to Battery */
    ui_process_event(&s, EVENT_VOLUME_DOWN);
    TEST_ASSERT_EQUAL(UI_SCREEN_BATTERY, s.home_highlighted);
}

void test_A18_encoder_cw_wraps_from_battery_to_record(void)
{
    ui_init(&s);
    /* scroll down 6 times to wrap all the way round */
    for (int i = 0; i < 6; i++) {
        ui_process_event(&s, EVENT_VOLUME_UP);
    }
    TEST_ASSERT_EQUAL(UI_SCREEN_RECORD, s.home_highlighted);
}

void test_A19_encoder_push_navigates_to_highlighted(void)
{
    /* Scroll to Effects then push — should enter Effects screen */
    ui_init(&s);
    ui_process_event(&s, EVENT_VOLUME_UP);  /* Play */
    ui_process_event(&s, EVENT_VOLUME_UP);  /* Effects */
    ui_process_event(&s, EVENT_MUTE_TOGGLE); /* push = select */
    TEST_ASSERT_EQUAL(UI_SCREEN_EFFECTS, s.screen);
}

void test_A20_encoder_push_on_home_does_not_mute(void)
{
    /* Encoder push on home = select, not mute */
    ui_init(&s);
    ui_process_event(&s, EVENT_MUTE_TOGGLE);
    TEST_ASSERT_FALSE(s.muted);
}

void test_A21_touch_tap_bypasses_cursor(void)
{
    /* Touch tap navigates directly regardless of cursor position */
    ui_init(&s);
    ui_process_event(&s, EVENT_VOLUME_UP);   /* cursor moves to Play */
    ui_process_event(&s, EVENT_NAV_BATTERY); /* tap Battery directly */
    TEST_ASSERT_EQUAL(UI_SCREEN_BATTERY, s.screen);
}

void test_A22_touch_tap_updates_cursor(void)
{
    /* Touch tap also moves the cursor to match what was tapped */
    ui_init(&s);
    ui_process_event(&s, EVENT_NAV_VOLUME);
    TEST_ASSERT_EQUAL(UI_SCREEN_VOLUME, s.home_highlighted);
}

void test_A23_mute_still_works_on_non_home_screens(void)
{
    /* Encoder push mutes normally on all screens except home */
    ui_init(&s);
    ui_process_event(&s, EVENT_NAV_PLAY);
    ui_process_event(&s, EVENT_MUTE_TOGGLE);
    TEST_ASSERT_TRUE(s.muted);
}

