void test_C14_selecting_different_effect_deactivates_previous(void)
{
    ui_init(&s);
    ui_process_event(&s, EVENT_NAV_EFFECTS);
    /* activate effect 1 */
    ui_process_event(&s, EVENT_EFFECT_SELECT);
    TEST_ASSERT_EQUAL(EFFECT_1, s.active_effect);
    /* scroll to effect 2 and select it */
    ui_process_event(&s, EVENT_EFFECT_SCROLL_DOWN);
    ui_process_event(&s, EVENT_EFFECT_SELECT);
    /* effect 2 now active, effect 1 deactivated */
    TEST_ASSERT_EQUAL(EFFECT_2, s.active_effect);
}

