void test_J10_cross_mode_play_coord_on_volume_returns_none(void)
{
    /* The Volume "+" button centre (120,174) lies in the gap between the
     * two tile columns on Home, so there it is no event at all */
    ui_event_t home_event = touch_get_event(VOL_CX(1), VOL_CY,
                                             UI_SCREEN_HOME);
    ui_event_t vol_event  = touch_get_event(VOL_CX(1), VOL_CY,
                                             UI_SCREEN_VOLUME);
    /* The events must differ — same coords, different screens */
    TEST_ASSERT_NOT_EQUAL(home_event, vol_event);

    /* The "-" centre (44,174) is inside a Home tile (Effects): a real
     * event on both screens, and still a different one */
    ui_event_t home_minus = touch_get_event(VOL_CX(0), VOL_CY, UI_SCREEN_HOME);
    TEST_ASSERT_NOT_EQUAL(EVENT_NONE, home_minus);
    TEST_ASSERT_NOT_EQUAL(home_minus, touch_get_event(VOL_CX(0), VOL_CY, UI_SCREEN_VOLUME));
}

