void test_J18_record_replaces_looping_playback(void)
{
    ui_init(&s);
    ui_process_event(&s, EVENT_BTN_PLAYPAUSE);
    ui_process_event(&s, EVENT_BTN_RECORD);
    TEST_ASSERT_EQUAL(PLAYBACK_RECORDING, s.playback);
    TEST_ASSERT_EQUAL(UI_SCREEN_RECORD, s.screen);

    ui_init(&s);
    ui_process_event(&s, EVENT_BTN_PLAYPAUSE);
    ui_process_event(&s, EVENT_BTN_PLAYPAUSE);         /* paused */
    ui_process_event(&s, EVENT_NAV_RECORD);            /* from Play: not home, no-op */
    ui_process_event(&s, EVENT_GO_HOME);
    ui_process_event(&s, EVENT_NAV_RECORD);
    ui_process_event(&s, EVENT_RECORD_START);
    TEST_ASSERT_EQUAL(PLAYBACK_RECORDING, s.playback);
}

