/* Full touch pipeline — ADC → pixel → event → state change
 * for a sub-screen action, confirming the complete chain works. */
void test_J28_touch_pipeline_record_start(void)
{
    ui_init(&s);
    ui_process_event(&s, EVENT_NAV_RECORD);

    /* Synthesise the ADC reading a tap on the centre of row 0 on the
     * record screen gives (adc_tap, group H: back through the panel
     * rotation and calibration), then run it through the full pipeline. */
    uint16_t target_x = ITEM_CX;
    uint16_t target_y = ITEM_CY(0);

    uint16_t px = 0U, py = 0U;
    TEST_ASSERT_TRUE(adc_tap(UI_PORTRAIT_ROTATION, target_x, target_y, &px, &py));
    TEST_ASSERT_EQUAL(target_x, px);
    TEST_ASSERT_EQUAL(target_y, py);
    ui_event_t e = touch_get_event(px, py, s.screen);
    ui_process_event(&s, e);

    TEST_ASSERT_EQUAL(PLAYBACK_RECORDING, s.playback);
}

void test_J29_status_band_is_dead_on_every_screen(void)
{
    /* No touch target on Home .. Battery reaches into the footer at the
     * bottom (STATUS_BAR_Y .. SCREEN_H-1 = y 294..319, the full width). */
    for (int sc = (int)UI_SCREEN_HOME; sc <= (int)UI_SCREEN_BATTERY; sc++) {
        for (uint16_t y = STATUS_BAR_Y; y < SCREEN_H; y++) {
            for (uint16_t x = 0U; x < SCREEN_W; x++) {
                TEST_ASSERT_EQUAL(EVENT_NONE, touch_get_event(x, y, (ui_screen_t)sc));
            }
        }
    }
}

void test_J30_play_box_and_home_box_do_not_overlap(void)
{
    /* The play box's top corners (52,72) and (187,72) still play / pause,
     * the HOME box's bottom-left pixel (152,71) still goes home, and the
     * play box starts at or below the HOME box's bottom edge. */
    const uint16_t play_x0 = PLAY_BTN_X - PLAY_HIT_PAD;
    const uint16_t play_x1 = PLAY_BTN_X + PLAY_BTN_W + PLAY_HIT_PAD - 1U;
    const uint16_t play_y0 = PLAY_BTN_Y - PLAY_HIT_PAD;

    TEST_ASSERT_EQUAL(EVENT_BTN_PLAYPAUSE, touch_get_event(play_x0, play_y0, UI_SCREEN_PLAY));
    TEST_ASSERT_EQUAL(EVENT_BTN_PLAYPAUSE, touch_get_event(play_x1, play_y0, UI_SCREEN_PLAY));
    TEST_ASSERT_EQUAL(EVENT_GO_HOME,
                      touch_get_event(HOME_HIT_X, HOME_HIT_Y + HOME_HIT_H - 1U, UI_SCREEN_PLAY));
    TEST_ASSERT_TRUE(play_y0 >= HOME_HIT_Y + HOME_HIT_H);
}

void test_J31_header_is_dead_on_every_screen(void)
{
    /* The power header across the top (y 0 .. HEADER_H-1 = 0..33, the full
     * width) is not a tap target on Home .. Battery, so a tap just above
     * HOME or a tile does nothing. The fault screen still closes on a tap
     * anywhere, the header included. */
    for (int sc = (int)UI_SCREEN_HOME; sc <= (int)UI_SCREEN_BATTERY; sc++) {
        for (uint16_t y = 0U; y < HEADER_H; y++) {
            for (uint16_t x = 0U; x < SCREEN_W; x++) {
                TEST_ASSERT_EQUAL(EVENT_NONE, touch_get_event(x, y, (ui_screen_t)sc));
            }
        }
    }
    for (uint16_t y = 0U; y < HEADER_H; y++) {
        for (uint16_t x = 0U; x < SCREEN_W; x++) {
            TEST_ASSERT_EQUAL(EVENT_FAULT_DISMISS, touch_get_event(x, y, UI_SCREEN_FAULT));
        }
    }
    /* The HOME box starts on the first row under the header (152,34). */
    TEST_ASSERT_EQUAL(EVENT_GO_HOME, touch_get_event(HOME_HIT_X, HEADER_H, UI_SCREEN_RECORD));
}

