/* Battery screen as the firmware glue fills it from a VALID battery
 * message: charge, voltage, the current now and its 2-minute average set,
 * discharging, no time estimate yet (ui_init's 65535). Tests then change
 * what they need. */
static void battery_screen(uint8_t pct, uint16_t mv, int16_t ma_now, int16_t ma_avg)
{
    ui_init(&s);
    s.screen         = UI_SCREEN_BATTERY;
    s.battery_valid  = true;
    s.battery_pct    = pct;
    s.battery_mv     = mv;
    s.battery_ma_now = ma_now;
    s.battery_ma_avg = ma_avg;
}

/* Size-2 info lines: 12 px per character on the 240 px wide portrait screen = 20 max. */
static void assert_battery_lines_fit(const display_info_t *d)
{
    TEST_ASSERT_LESS_OR_EQUAL_UINT(20U, strlen(d->line1));
    TEST_ASSERT_LESS_OR_EQUAL_UINT(20U, strlen(d->line2));
    TEST_ASSERT_LESS_OR_EQUAL_UINT(20U, strlen(d->line3));
    TEST_ASSERT_LESS_OR_EQUAL_UINT(20U, strlen(d->line4));
    TEST_ASSERT_LESS_OR_EQUAL_UINT(20U, strlen(d->line5));
    TEST_ASSERT_LESS_OR_EQUAL_UINT(20U, strlen(d->line6));
}

void test_K10_battery_screen_discharging_lines(void)
{
    battery_screen(80U, 3712U, -152, -140);
    s.battery_tte_min = 75U;                  /* time to empty; time to full stays 65535 */
    ui_get_display_info(&s, &disp);
    TEST_ASSERT_EQUAL_STRING("Charge  80%", disp.line1);
    TEST_ASSERT_EQUAL_STRING("Current   -152 mA", disp.line2);     /* the last second */
    TEST_ASSERT_EQUAL_STRING("Average   -140 mA", disp.line3);     /* the 2-minute average */
    TEST_ASSERT_EQUAL_STRING("Voltage  3.712 V", disp.line4);
    TEST_ASSERT_EQUAL_STRING("Time left 01:15", disp.line5);
    TEST_ASSERT_EQUAL_STRING("Status Discharging ", disp.line6);
}

void test_K11_battery_screen_charging_lines(void)
{
    /* Charging into the battery: Brendon sends a time to full and no time
     * to empty. */
    battery_screen(45U, 3650U, 850, 820);
    s.battery_charging = true;
    s.battery_ttf_min  = 42U;
    ui_get_display_info(&s, &disp);
    TEST_ASSERT_EQUAL_STRING("Charge  45%", disp.line1);
    TEST_ASSERT_EQUAL_STRING("Current   +850 mA", disp.line2);
    TEST_ASSERT_EQUAL_STRING("Average   +820 mA", disp.line3);
    TEST_ASSERT_EQUAL_STRING("Voltage  3.650 V", disp.line4);
    TEST_ASSERT_EQUAL_STRING("To full   00:42", disp.line5);
    TEST_ASSERT_EQUAL_STRING("Status Charging    ", disp.line6);
}

void test_K11b_battery_screen_draining_on_the_charger(void)
{
    /* Loud music takes more than the charger gives: the battery drains
     * although it is plugged in. Brendon then sends a time to empty and
     * no time to full; the screen shows that time and "Plugged in". */
    battery_screen(90U, 4150U, -310, -30);
    s.battery_charging = true;
    s.battery_tte_min  = 3000U;
    ui_get_display_info(&s, &disp);
    TEST_ASSERT_EQUAL_STRING("Current   -310 mA", disp.line2);     /* a loud second */
    TEST_ASSERT_EQUAL_STRING("Average    -30 mA", disp.line3);
    TEST_ASSERT_EQUAL_STRING("Time left 50:00", disp.line5);
    TEST_ASSERT_EQUAL_STRING("Status Plugged in  ", disp.line6);

    /* The music stops: charging again. */
    s.battery_tte_min = UI_TIME_UNKNOWN;
    s.battery_ttf_min = 25U;
    ui_get_display_info(&s, &disp);
    TEST_ASSERT_EQUAL_STRING("To full   00:25", disp.line5);
    TEST_ASSERT_EQUAL_STRING("Status Charging    ", disp.line6);
}

void test_K11c_battery_screen_full(void)
{
    /* Full on the charger: a time to full of 0 is "Full". */
    battery_screen(100U, 4190U, 20, 15);
    s.battery_charging = true;
    s.battery_ttf_min  = 0U;
    ui_get_display_info(&s, &disp);
    TEST_ASSERT_EQUAL_STRING("To full   00:00", disp.line5);
    TEST_ASSERT_EQUAL_STRING("Status Full        ", disp.line6);

    /* Full, but the speakers take more than the charger gives: still
     * "Full", and the line shows how long the battery lasts like that. */
    s.battery_tte_min = 4080U;
    ui_get_display_info(&s, &disp);
    TEST_ASSERT_EQUAL_STRING("Time left 68:00", disp.line5);
    TEST_ASSERT_EQUAL_STRING("Status Full        ", disp.line6);

    /* The charger says the charge is complete (not charging): "Full" and
     * the time to empty of the load. */
    s.battery_charging = false;
    s.battery_tte_min  = 1500U;
    ui_get_display_info(&s, &disp);
    TEST_ASSERT_EQUAL_STRING("Time left 25:00", disp.line5);
    TEST_ASSERT_EQUAL_STRING("Status Full        ", disp.line6);
}

