    debug_turn(EVENT_VOLUME_UP, DEBUG_FULL_TURN);
    assert_debug_at(DEBUG_PAGE_SPEAKER, 4U);
    debug_turn(EVENT_VOLUME_DOWN, DEBUG_FULL_TURN);
    assert_debug_at(DEBUG_PAGE_SPEAKER, 4U);
