    assert_debug_at(DEBUG_PAGE_FAULTS, 0U);
    ui_show_fault(&s, UI_FAULT_SRC_STORAGE, (uint8_t)(1U | UI_FAULT_CODE_SIMULATED),
                  "SD card removed", "Recording stopped");
    ui_get_display_info(&s, &disp);
    TEST_ASSERT_EQUAL_STRING("Storage (simulated)", disp.line1);

