void test_P16_back_hold_pipeline_opens_debug(void)
{
    /* The firmware's order on every 10 ms scan: BACK's press edge sends
     * EVENT_GO_HOME (nothing to do on Home), and the hold detector is fed
     * the button level; when it returns 1 the glue calls ui_enter_debug. */
    debug_hold_t h;
    const uint32_t t0 = 5000U;

    debug_hold_init(&h);
    ui_init(&s);
    ui_process_event(&s, EVENT_GO_HOME);         /* the press edge */
    for (uint32_t ms = 0U; ms < DEBUG_HOLD_MS; ms += 10U) {
        if (debug_hold_update(&h, 1U, (uint8_t)(s.screen == UI_SCREEN_HOME), t0 + ms)) {
            ui_enter_debug(&s);
        }
        TEST_ASSERT_EQUAL(UI_SCREEN_HOME, s.screen);   /* under 2 s: still Home */
    }
    if (debug_hold_update(&h, 1U, (uint8_t)(s.screen == UI_SCREEN_HOME), t0 + DEBUG_HOLD_MS)) {
        ui_enter_debug(&s);
    }
    assert_debug_at(DEBUG_PAGE_SYSTEM, 0U);

    /* Held on, then released: nothing more happens (once per press). */
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&h, 1U, 0U, t0 + DEBUG_HOLD_MS + 500U));
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&h, 0U, 0U, t0 + DEBUG_HOLD_MS + 600U));
    assert_debug_at(DEBUG_PAGE_SYSTEM, 0U);

    /* The next short BACK press leaves. */
    ui_process_event(&s, EVENT_GO_HOME);
    TEST_ASSERT_EQUAL(UI_SCREEN_HOME, s.screen);
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP Q — Effects: a tap picks the tapped row
 * Each Effects row sends its own EVENT_EFFECT_PICK_n (touch_region.c):
 * the tapped row becomes the cursor and is toggled like a select, so the
 * effect that turns on (or off) is the one tapped, wherever the encoder
 * cursor was (EFFECT_1, Autotune, after boot).
 * ═══════════════════════════════════════════════════════════════════════ */

/* A tap on the centre of Effects row n, through the touch mapping. */
static void effects_tap_row(uint8_t n)
{
    ui_process_event(&s, touch_get_event(ITEM_CX, ITEM_CY(n), s.screen));
}

void test_Q01_tap_turns_on_the_tapped_row(void)
{
    ui_init(&s);
    ui_process_event(&s, EVENT_NAV_EFFECTS);
    TEST_ASSERT_EQUAL(EFFECT_1, s.effect_highlighted);  /* the cursor on row 0 */
    effects_tap_row(5U);
    TEST_ASSERT_EQUAL(EFFECT_6, s.active_effect);
    TEST_ASSERT_EQUAL(EFFECT_6, s.effect_highlighted);

    /* Every row, from a fresh start: its own effect, not the cursor's. */
    for (uint8_t n = 0U; n < MENU_ITEM_COUNT; n++) {
        ui_init(&s);
        ui_process_event(&s, EVENT_NAV_EFFECTS);
        effects_tap_row(n);
        TEST_ASSERT_EQUAL(EFFECT_1 + n, s.active_effect);
        TEST_ASSERT_EQUAL(EFFECT_1 + n, s.effect_highlighted);
    }
}

void test_Q02_tap_the_active_row_again_turns_it_off(void)
{
    ui_init(&s);
    ui_process_event(&s, EVENT_NAV_EFFECTS);
    effects_tap_row(5U);
    effects_tap_row(5U);
    TEST_ASSERT_EQUAL(EFFECT_NONE, s.active_effect);
    TEST_ASSERT_EQUAL(EFFECT_6, s.effect_highlighted);  /* the cursor stays on it */
}

void test_Q03_tap_another_row_switches_effect(void)
{
    ui_init(&s);
    ui_process_event(&s, EVENT_NAV_EFFECTS);
    effects_tap_row(5U);                                /* EFFECT_6 on */
    effects_tap_row(2U);
    TEST_ASSERT_EQUAL(EFFECT_3, s.active_effect);
    TEST_ASSERT_EQUAL(EFFECT_3, s.effect_highlighted);
}

void test_Q04_encoder_push_after_a_pick_toggles_that_row(void)
{
    ui_init(&s);
    ui_process_event(&s, EVENT_NAV_EFFECTS);
    effects_tap_row(3U);                                /* EFFECT_4 on, cursor on it */
    ui_process_event(&s, EVENT_MUTE_TOGGLE);            /* encoder push: off again */
    TEST_ASSERT_EQUAL(EFFECT_NONE, s.active_effect);
    TEST_ASSERT_FALSE(s.muted);
    ui_process_event(&s, EVENT_MUTE_TOGGLE);            /* and on */
    TEST_ASSERT_EQUAL(EFFECT_4, s.active_effect);

    /* The encoder carries on from the picked row. */
    ui_process_event(&s, EVENT_VOLUME_UP);
    ui_process_event(&s, EVENT_MUTE_TOGGLE);
    TEST_ASSERT_EQUAL(EFFECT_5, s.effect_highlighted);
    TEST_ASSERT_EQUAL(EFFECT_5, s.active_effect);
}

void test_Q05_pick_changes_nothing_on_other_screens(void)
{
    /* Only the Effects rows send these events. Anywhere else they must not
     * touch the effect, the cursor or anything else. (The fault screen
     * closes on them as on every input, O10; the debug screen ignores
     * them, P11.) */
    static const ui_screen_t screens[] = { UI_SCREEN_HOME, UI_SCREEN_RECORD, UI_SCREEN_PLAY,
                                           UI_SCREEN_VOLUME, UI_SCREEN_FILE, UI_SCREEN_BATTERY };

    for (size_t i = 0U; i < sizeof(screens) / sizeof(screens[0]); i++) {
        for (int ev = (int)EVENT_EFFECT_PICK_1; ev <= (int)EVENT_EFFECT_PICK_6; ev++) {
            setup_busy_volume_screen();                 /* effect 2 on, cursor on effect 1 */
            s.screen = screens[i];
            ui_process_event(&s, (ui_event_t)ev);
            TEST_ASSERT_EQUAL(screens[i], s.screen);
            assert_busy_state_unchanged();
        }
    }
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP R — Effect files: Preparing, n/a, following Jack by seq, REC clock
 * ═══════════════════════════════════════════════════════════════════════ */

void test_R01_init_shows_no_preparing_and_no_na(void)
{
    ui_init(&s);
    TEST_ASSERT_EQUAL_UINT8(UI_PREP_NONE, s.prep_pct);
    TEST_ASSERT_FALSE(s.fx_na);
}

void test_R02_no_event_changes_prep_pct_or_fx_na(void)
{
    /* Both are copied from Jack's status by the firmware glue; the state
     * machine only reads them. */
    for (int sc = (int)UI_SCREEN_HOME; sc <= (int)UI_SCREEN_BATTERY; sc++) {
        for (int ev = 0; ev < (int)EVENT_COUNT; ev++) {
            ui_init(&s);
            s.screen   = (ui_screen_t)sc;
            s.prep_pct = 45U;
            s.fx_na    = true;
            ui_process_event(&s, (ui_event_t)ev);
            TEST_ASSERT_EQUAL_UINT8(45U, s.prep_pct);
            TEST_ASSERT_TRUE(s.fx_na);
        }
    }
}

void test_R03_play_line_1_says_preparing_with_the_percent(void)
{
    ui_init(&s);
    s.screen   = UI_SCREEN_PLAY;
    s.playback = PLAYBACK_PLAYING;
    s.prep_pct = 45U;
    ui_get_display_info(&s, &disp);
    TEST_ASSERT_EQUAL_STRING("Preparing 45%", disp.line1);
    s.prep_pct = 0U;
    ui_get_display_info(&s, &disp);
    TEST_ASSERT_EQUAL_STRING("Preparing 0%", disp.line1);
    s.prep_pct = 100U;
    ui_get_display_info(&s, &disp);
    TEST_ASSERT_EQUAL_STRING("Preparing 100%", disp.line1);
    TEST_ASSERT_LESS_OR_EQUAL_UINT(14U, strlen(disp.line1));
    TEST_ASSERT_TRUE(ui_is_preparing(&s));
}

void test_R04_play_line_1_says_playing_when_nothing_is_prepared(void)
{
    ui_init(&s);
    s.screen   = UI_SCREEN_PLAY;
    s.playback = PLAYBACK_PLAYING;
    ui_get_display_info(&s, &disp);                 /* prep_pct UI_PREP_NONE */
    TEST_ASSERT_EQUAL_STRING("Playing (loop)", disp.line1);
    TEST_ASSERT_FALSE(ui_is_preparing(&s));

    s.playback = PLAYBACK_PAUSED;                   /* paused while it was prepared */
    s.prep_pct = 45U;
    ui_get_display_info(&s, &disp);
    TEST_ASSERT_EQUAL_STRING("Paused", disp.line1);
    TEST_ASSERT_FALSE(ui_is_preparing(&s));
    TEST_ASSERT_FALSE(ui_is_preparing(NULL));
}

void test_R05_play_line_2_says_none_na_when_the_effect_is_not_available(void)
{
    ui_init(&s);
    s.screen        = UI_SCREEN_PLAY;
    s.playback      = PLAYBACK_PLAYING;
    s.active_effect = EFFECT_5;                     /* Echo */
    ui_get_display_info(&s, &disp);
    TEST_ASSERT_EQUAL_STRING("Effect: Echo", disp.line2);
    s.fx_na = true;                                 /* the original plays instead */
    ui_get_display_info(&s, &disp);
    TEST_ASSERT_EQUAL_STRING("Effect: None (n/a)", disp.line2);
    TEST_ASSERT_LESS_OR_EQUAL_UINT(20U, strlen(disp.line2));
}

void test_R06_follow_jack_to_idle_at_once_when_the_seq_matches(void)
{
    /* Jack's status carries Tony's newest command seq: it describes him
     * after that command, so it is trusted at once (here 10 ms after the
     * command, inside the old 1 s blackout). */
    TEST_ASSERT_TRUE(ui_follow_jack_idle(PLAYBACK_PLAYING, false, 0U, true, 10U));
    TEST_ASSERT_TRUE(ui_follow_jack_idle(PLAYBACK_PAUSED, false, 0U, true, 0U));
    TEST_ASSERT_TRUE(ui_follow_jack_idle(PLAYBACK_RECORDING, false, 0U, true, 0U));
    /* Already idle: nothing to follow */
    TEST_ASSERT_FALSE(ui_follow_jack_idle(PLAYBACK_IDLE, false, 0U, true, 5000U));
}

void test_R07_follow_jack_to_idle_after_1_s_when_the_seq_differs(void)
{
    /* An older status (Jack has not taken the command yet), or a command
     * lost to a full queue: the old rule, 1 s after the last command. */
    TEST_ASSERT_FALSE(ui_follow_jack_idle(PLAYBACK_PLAYING, false, 0U, false, 10U));
    TEST_ASSERT_FALSE(ui_follow_jack_idle(PLAYBACK_PLAYING, false, 0U, false, UI_CMD_RECONCILE_MS));
    TEST_ASSERT_TRUE(ui_follow_jack_idle(PLAYBACK_PLAYING, false, 0U, false, UI_CMD_RECONCILE_MS + 1U));
}

void test_R08_never_follow_jack_to_idle_while_he_prepares_records_or_plays(void)
{
    for (int seq = 0; seq <= 1; seq++) {
        TEST_ASSERT_FALSE(ui_follow_jack_idle(PLAYBACK_PLAYING, false, 3U, seq != 0, 60000U));   /* preparing */
        TEST_ASSERT_FALSE(ui_follow_jack_idle(PLAYBACK_PLAYING, false, 1U, seq != 0, 60000U));   /* playing */
        TEST_ASSERT_FALSE(ui_follow_jack_idle(PLAYBACK_PAUSED, false, 2U, seq != 0, 60000U));    /* paused */
        TEST_ASSERT_FALSE(ui_follow_jack_idle(PLAYBACK_RECORDING, true, 0U, seq != 0, 60000U));  /* recording */
    }
}

void test_R09_a_delete_answer_then_a_play_keeps_playing(void)
{
    /* The user deletes a file, then presses PLAY before Jack has answered.
     * Jack's status after the DELETE says idle, with the DELETE's seq; the
     * PLAY_START is newer, so that status is not about the PLAY: the UI
     * stays PLAYING (the PLAY's own ack and status follow). */
    ui_init(&s);
    ui_process_event(&s, EVENT_BTN_PLAYPAUSE);      /* PLAY: IDLE -> PLAYING */
    TEST_ASSERT_EQUAL(PLAYBACK_PLAYING, s.playback);
    TEST_ASSERT_FALSE(ui_follow_jack_idle(s.playback, false, 0U, false /* DELETE's seq, not PLAY's */, 150U));
}

void test_R10_the_rec_clock_starts_on_jacks_recording_status_without_an_ack(void)
{
    /* Jack's status saying he records starts the clock, once; no ack is
     * needed (the status usually comes first, and the ack may be lost). */
    TEST_ASSERT_TRUE(ui_rec_clock_start(PLAYBACK_RECORDING, true, false));
    TEST_ASSERT_FALSE(ui_rec_clock_start(PLAYBACK_RECORDING, true, true));     /* already running */
    TEST_ASSERT_FALSE(ui_rec_clock_start(PLAYBACK_RECORDING, false, false));   /* Jack not recording yet */
    TEST_ASSERT_FALSE(ui_rec_clock_start(PLAYBACK_IDLE, true, false));         /* the UI stopped it */
    TEST_ASSERT_FALSE(ui_rec_clock_start(PLAYBACK_PLAYING, true, false));
}

